import json
import boto3
import os
import uuid
from datetime import datetime
from boto3.dynamodb.conditions import Key, Attr

# Global: DynamoDB resource — reused across warm invocations
dynamodb = boto3.resource('dynamodb')
table = dynamodb.Table(os.environ['TABLE_NAME'])

def lambda_handler(event, context):
    method = event.get('httpMethod')
    path   = event.get('path', '')

    if method == 'GET' and path == '/orders':
        return get_orders(event)
    elif method == 'GET' and '{orderId}' in path:
        return get_order(event)
    elif method == 'POST' and path == '/orders':
        return create_order(event)
    elif method == 'PUT':
        return update_order(event)
    elif method == 'DELETE':
        return delete_order(event)
    return build_response(404, {'error': 'Route not found'})

# ---- GET all orders for a user ----
def get_orders(event):
    user_id = event.get('queryStringParameters', {}).get('userId')
    if not user_id:
        return build_response(400, {'error': 'userId query param required'})

    # Query by PK — efficient! Never scan for this.
    response = table.query(
        KeyConditionExpression=Key('PK').eq(f'USER#{user_id}') &
                               Key('SK').begins_with('ORDER#')
    )
    return build_response(200, response['Items'])

# ---- GET single order ----
def get_order(event):
    order_id = event['pathParameters']['orderId']
    user_id  = event.get('queryStringParameters', {}).get('userId')

    response = table.get_item(
        Key={'PK': f'USER#{user_id}', 'SK': f'ORDER#{order_id}'}
    )
    item = response.get('Item')
    if not item:
        return build_response(404, {'error': 'Order not found'})
    return build_response(200, item)

# ---- POST create order ----
def create_order(event):
    body = json.loads(event.get('body') or '{}')
    user_id  = body.get('userId')
    items    = body.get('items', [])
    if not user_id or not items:
        return build_response(400, {'error': 'userId and items are required'})

    order_id = str(uuid.uuid4())
    order = {
        'PK':        f'USER#{user_id}',
        'SK':        f'ORDER#{order_id}',
        'orderId':   order_id,
        'userId':    user_id,
        'items':     items,
        'status':    'PENDING',
        'createdAt': datetime.utcnow().isoformat(),
    }
    table.put_item(Item=order)
    return build_response(201, order)

# ---- PUT update order status ----
def update_order(event):
    order_id = event['pathParameters']['orderId']
    body     = json.loads(event.get('body') or '{}')
    user_id  = body.get('userId')
    status   = body.get('status')
    if not status:
        return build_response(400, {'error': 'status is required'})

    # Conditional update — only update if order exists
    response = table.update_item(
        Key={'PK': f'USER#{user_id}', 'SK': f'ORDER#{order_id}'},
        UpdateExpression='SET #s = :status, updatedAt = :now',
        ExpressionAttributeNames={'#s': 'status'},   # 'status' is reserved
        ExpressionAttributeValues={
            ':status': status,
            ':now': datetime.utcnow().isoformat()
        },
        ConditionExpression=Attr('orderId').exists(),
        ReturnValues='ALL_NEW'
    )
    return build_response(200, response.get('Attributes', {}))

# ---- DELETE order ----
def delete_order(event):
    order_id = event['pathParameters']['orderId']
    user_id  = event.get('queryStringParameters', {}).get('userId')

    table.delete_item(Key={'PK': f'USER#{user_id}', 'SK': f'ORDER#{order_id}'})
    return build_response(204, {})

def build_response(status_code, body):
    return {
        'statusCode': status_code,
        'headers': {'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*'},
        'body': json.dumps(body, default=str)
    }

const { DynamoDBClient } = require('@aws-sdk/client-dynamodb');
const { DynamoDBDocumentClient, GetCommand, PutCommand, QueryCommand, UpdateCommand } = require('@aws-sdk/lib-dynamodb');
const { randomUUID } = require('crypto');

const client = new DynamoDBClient({});
const ddb = DynamoDBDocumentClient.from(client);
const TABLE = process.env.TABLE_NAME;

exports.handler = async (event) => {
  const { httpMethod, path, pathParameters, queryStringParameters } = event;
  const body = event.body ? JSON.parse(event.body) : {};

  try {
    if (httpMethod === 'GET' && path === '/orders') {
      const { userId } = queryStringParameters || {};
      if (!userId) return respond(400, { error: 'userId required' });
      const { Items } = await ddb.send(new QueryCommand({
        TableName: TABLE,
        KeyConditionExpression: 'PK = :pk AND begins_with(SK, :sk)',
        ExpressionAttributeValues: { ':pk': `USER#${userId}`, ':sk': 'ORDER#' }
      }));
      return respond(200, Items);
    }

    if (httpMethod === 'POST' && path === '/orders') {
      const orderId = randomUUID();
      const item = { PK: `USER#${body.userId}`, SK: `ORDER#${orderId}`, orderId, status: 'PENDING', ...body };
      await ddb.send(new PutCommand({ TableName: TABLE, Item: item }));
      return respond(201, item);
    }
  } catch (err) {
    console.error(err);
    return respond(500, { error: 'Internal Server Error' });
  }
};

const respond = (statusCode, body) => ({
  statusCode,
  headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' },
  body: JSON.stringify(body)
});

import json
import boto3
import os
import logging
import uuid

logger = logging.getLogger()
logger.setLevel(logging.INFO)

# Initialize SQS client globally
sqs = boto3.client('sqs')
QUEUE_URL = os.environ['QUEUE_URL']

def lambda_handler(event, context):
    """
    Producer Lambda — sends order messages to SQS queue.
    Invoked synchronously by API Gateway.
    """
    body = json.loads(event.get('body') or '{}')
    orders = body.get('orders', [])

    if not orders:
        return build_response(400, {'error': 'orders list required'})

    if len(orders) == 1:
        # Single message
        order = orders[0]
        response = sqs.send_message(
            QueueUrl=QUEUE_URL,
            MessageBody=json.dumps(order),
            # For FIFO queues only:
            # MessageGroupId=f"user-{order['userId']}",
            # MessageDeduplicationId=str(uuid.uuid4()),
            MessageAttributes={
                'eventType': {
                    'DataType': 'String',
                    'StringValue': 'ORDER_CREATED'
                }
            }
        )
        logger.info("Sent message: %s", response['MessageId'])
        return build_response(202, {'messageId': response['MessageId']})

    # Batch send up to 10 messages at once (cheaper, faster)
    entries = [
        {
            'Id': str(i),                          # Batch item ID (not SQS msg ID)
            'MessageBody': json.dumps(order),
            'MessageAttributes': {
                'eventType': {'DataType': 'String', 'StringValue': 'ORDER_CREATED'}
            }
        }
        for i, order in enumerate(orders[:10])    # SQS batch max = 10
    ]

    response = sqs.send_message_batch(QueueUrl=QUEUE_URL, Entries=entries)

    failed = response.get('Failed', [])
    if failed:
        logger.error("Batch send failures: %s", failed)
        return build_response(207, {
            'sent': len(response.get('Successful', [])),
            'failed': len(failed),
            'failures': failed
        })

    return build_response(202, {'sent': len(entries)})

def build_response(status, body):
    return {
        'statusCode': status,
        'headers': {'Content-Type': 'application/json'},
        'body': json.dumps(body)
    }

