import boto3
from datetime import datetime, timezone, timedelta

def audit_certificates(regions=['us-east-1', 'ap-south-1']):
    report = {'total': 0, 'issued': 0, 'expiring_30d': [], 'failed': []}
    threshold = datetime.now(timezone.utc) + timedelta(days=30)
    for region in regions:
        acm = boto3.client('acm', region_name=region)
        certs = acm.list_certificates(Includes={'keyTypes': ['RSA_2048', 'EC_prime256v1']})
        for c in certs['CertificateSummaryList']:
            report['total'] += 1
            desc = acm.describe_certificate(CertificateArn=c['CertificateArn'])
            cert = desc['Certificate']
            if cert['Status'] == 'ISSUED':
                report['issued'] += 1
                if cert.get('NotAfter') and cert['NotAfter'] < threshold:
                    report['expiring_30d'].append({'domain': cert['DomainName'], 'region': region, 'expires': str(cert['NotAfter'])})
            elif cert['Status'] == 'FAILED':
                report['failed'].append({'domain': cert['DomainName'], 'region': region, 'reason': cert.get('FailureReason', 'UNKNOWN')})
    return report

