    now = time.time()
    start = now - (hours_back * 3600)
    graph = xray.get_service_graph(StartTime=start, EndTime=now)
    slowest = {'service': None, 'avg_latency_ms': 0}
    for svc in graph['Services']:
        if svc.get('ResponseTimeHistogram'):
            avg = sum(h['Value'] * h['Count'] for h in svc['ResponseTimeHistogram']) / max(sum(h['Count'] for h in svc['ResponseTimeHistogram']), 1)
            if avg > slowest['avg_latency_ms']:
                slowest = {'service': svc['Name'], 'avg_latency_ms': round(avg * 1000, 2)}
    return slowest

