import boto3

def threat_summary(detector_id):
    gd = boto3.client('guardduty')
    ids = gd.list_findings(DetectorId=detector_id, FindingCriteria={'Criterion': {'service.archived': {'Eq': ['false']}}})['FindingIds']
    summary = {'high': [], 'medium': [], 'low': [], 'total': len(ids)}
    if ids:
        findings = gd.get_findings(DetectorId=detector_id, FindingIds=ids[:50])['Findings']
        for f in findings:
            bucket = 'high' if f['Severity'] >= 7 else 'medium' if f['Severity'] >= 4 else 'low'
            summary[bucket].append(f['Type'])
    return summary

