import boto3

def vulnerability_report():
    inspector = boto3.client('inspector2')
    report = {'critical': 0, 'high': 0, 'medium': 0, 'low': 0, 'total': 0, 'fixable': 0}
    paginator = inspector.get_paginator('list_findings')
    for page in paginator.paginate(filterCriteria={'findingStatus': [{'comparison': 'EQUALS', 'value': 'ACTIVE'}]}):
        for f in page['findings']:
            report['total'] += 1
            severity = f['severity'].lower()
            if severity in report: report[severity] += 1
            if f.get('fixAvailable') == 'YES': report['fixable'] += 1
    return report

